import React from "react";
import "./VideoGrid.css";

function VideoGrid() {
  return (
    <div className="main">
    <div className="video-grid-container">
      {[...Array()].map((_, index) => (
        <div key={index} className="youtube-card">
          <div className="youtube-card-thumbnail">
            <img
              src="https://avatars.mds.yandex.net/i?id=ea2552b2dbee1b25c0dc20cab80b4604e5684af9-5690699-images-thumbs&n=13"
              alt="Video Thumbnail"
              className="thumbnail-image"
            />
          </div>
          <div className="youtube-card-content">
            <h3 className="video-title">Amazing Video Title </h3>
            <p className="channel-name">Channel Name</p>
            <div className="video-stats">
              <span className="views">1M views</span>
              <span className="time">2 days ago</span>
            </div>
          </div>
        </div>
      ))}
    </div>
    </div>

  );
}

export default VideoGrid;
